import * as THREE from 'three/webgpu';
import { texture, uv, color, mix, float } from 'three/tsl';
import gsap from 'gsap';
import { fontAtlas } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-2-label';
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Background plane (subtle machined-metal surface tint)
  const planeGeo = new THREE.PlaneGeometry(1.6, 0.4);
  const planeMat = new THREE.MeshBasicNodeMaterial({ transparent: true });

  let tex = null;
  try {
    tex = ctx.textureLoader('/prism-mock/home/nodes/floating-accent.png');
  } catch (e) {
    tex = null;
  }

  if (tex) {
    const texNode = texture(tex, uv());
    planeMat.colorNode = mix(color(colors.surface), texNode, float(0.85));
    planeMat.opacityNode = texNode.a;
  } else {
    planeMat.colorNode = color(colors.surface);
  }

  const plane = new THREE.Mesh(planeGeo, planeMat);
  plane.name = 'label-bg';
  group.add(plane);

  // Text: "Journal 3" headline via MSDF font atlas
  const textMesh = fontAtlas.createText({
    text: 'Journal 3',
    font: 'display',
    weight: 400,
    size: 0.34,
    color: colors.paper,
    anchor: 'center',
    atlas: ctx.fontAtlas,
  });
  textMesh.name = 'label-text';
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  // Accent edge frame (thin line using scaled plane, hidden by default, shown on focus)
  const accentGeo = new THREE.PlaneGeometry(1.64, 0.44);
  const accentMat = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0,
  });
  accentMat.colorNode = color(colors.accent);
  const accentEdge = new THREE.Mesh(accentGeo, accentMat);
  accentEdge.name = 'accent-edge';
  accentEdge.position.z = -0.005;
  accentEdge.material.opacity = 0;
  group.add(accentEdge);

  // Animation state
  const baseY = group.position.y;
  let hoverTween = null;
  let pressTween = null;
  let focusTween = null;

  const onHover = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverOut = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onClick = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      })
      .to(group.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.12,
        ease: 'back.out',
      });

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { itemId: config?.dataBindings?.[0]?.source ?? null });
    }
  };

  const onFocus = () => {
    if (focusTween) focusTween.kill();
    focusTween = gsap.to(accentMat, {
      opacity: 1,
      duration: 0.3,
      ease: 'power2.out',
    });
  };

  const onBlur = () => {
    if (focusTween) focusTween.kill();
    focusTween = gsap.to(accentMat, {
      opacity: 0,
      duration: 0.3,
      ease: 'power2.out',
    });
  };

  group.userData.handlers = {
    hover: onHover,
    hoverOut: onHoverOut,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
  };

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    if (focusTween) focusTween.kill();

    planeGeo.dispose();
    planeMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();

    if (tex && tex.dispose) tex.dispose();

    if (textMesh.userData?.cleanup) {
      textMesh.userData.cleanup();
    } else if (textMesh.geometry) {
      textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  return group;
}
